#pragma once

// Writes a new Bedrock world (.mcworld) containing a Bedrock structure
// (docs/formats/bedrock-world.md). The world is a superflat world; only the chunk
// columns the structure touches are written (with the flat layers filled in, so
// nothing floats over holes). All other chunks are generated by the game.

#include <bridger/core/result.hpp>
#include <bridger/core/structure.hpp>
#include <bridger/formats/bedrock/mcworld/level_dat.hpp>
#include <bridger/formats/bedrock/mcworld/subchunk_codec.hpp>

#include <filesystem>
#include <vector>

namespace bridger::formats::bedrock {

struct FlatLayer {
    u32 state = 0; // Bedrock state id (same domain as the structure's block layers)
    u32 count = 1;
};

struct NewWorldOptions {
    LevelDatOptions level;
    // World position of the structure's local (0,0,0).
    BlockPos origin{0, -60, 0};
    // --air replace: structure air clears the flat layers it overlaps (default: keep).
    bool air_replaces = false;
    // Superflat layers from y = -64 upward; must match level.flat_world_layers.
    std::vector<FlatLayer> flat_layers;
    u32 air_state = 0;
    i32 default_biome = 1; // Bedrock numeric biome id (plains)
};

struct WorldWriteStats {
    usize chunks = 0;
    usize subchunks = 0;
    usize block_entities = 0;
};

// Builds the world in `work_dir` (an empty scratch directory) and returns the zipped
// .mcworld bytes. The structure's block layers hold Bedrock state ids resolvable by
// `state_nbt`; its biome layers hold Bedrock numeric biome ids; its block entities
// hold Bedrock little-endian NBT without positions (x/y/z, pairx/pairz are added
// or offset here). Fails if any block lies outside the Overworld build height.
[[nodiscard]] Result<std::vector<u8>> write_new_world(const Structure& structure, const NewWorldOptions& options,
                                                      const StateNbtFn& state_nbt, const std::filesystem::path& work_dir,
                                                      WorldWriteStats* stats = nullptr);

// Checks a .mcworld produced by write_new_world: unzips it, opens the LevelDB copy,
// decodes every subchunk and parses level.dat and block entities. Used as the output
// validation before the atomic move (docs/safety.md).
[[nodiscard]] Status validate_mcworld(std::span<const u8> mcworld, const std::filesystem::path& work_dir,
                                      WorldWriteStats* stats = nullptr);

} // namespace bridger::formats::bedrock
